  "gm.srv.pkFollow": { en: "{name} looked and dared to follow (double {cups}) — cards open!", zh: "{name} 看了牌还敢跟（双倍 {cups}）——开牌！", id: "{name} sudah lihat dan berani ikut (dobel {cups}) — kartu dibuka!" },
  "gm.srv.pkFold": { en: "{name} looked and didn't dare 😱", zh: "{name} 看了牌不敢跟 😱", id: "{name} sudah lihat dan tidak berani 😱" },
  "gm.srv.pkFinish1": { en: "{why} — {names} drinks the whole pot: {cups} 🍻", zh: "{why}——{names} 喝掉整个池：{cups} 🍻", id: "{why} — {names} minum seluruh pot: {cups} 🍻" },
  "gm.srv.pkFinishN": { en: "{why} — {names} drink the whole pot: {cups} 🍻", zh: "{why}——{names} 喝掉整个池：{cups} 🍻", id: "{why} — {names} minum seluruh pot: {cups} 🍻" },
  "gm.srv.gbFree": { en: "🌉 {name} walks the known path and crosses safely!", zh: "🌉 {name} 沿着已知路线安全过桥！", id: "🌉 {name} melewati jalur yang diketahui dan menyeberang dengan aman!" },
  "gm.srv.gbTurn": { en: "{name}'s turn — row {n}: LEFT or RIGHT?", zh: "轮到 {name}——第 {n} 排：左还是右？", id: "Giliran {name} — baris {n}: KIRI atau KANAN?" },
  "gm.srv.gbAcross": { en: "🎉 {name} made it across the bridge!", zh: "🎉 {name} 成功过桥！", id: "🎉 {name} berhasil menyeberangi jembatan!" },
  "gm.srv.gbSafe": { en: "✅ {name} stepped {side} — safe! Row {n} next", zh: "✅ {name} 踩了{side}——安全！下一排：第 {n} 排", id: "✅ {name} melangkah ke {side} — aman! Berikutnya baris {n}" },
  "gm.srv.gbSafeAuto": { en: "✅ {name} stepped {side} — safe! Row {n} next (time ran out — random step)", zh: "✅ {name} 踩了{side}——安全！下一排：第 {n} 排（超时——随机走一步）", id: "✅ {name} melangkah ke {side} — aman! Berikutnya baris {n} (waktu habis — langkah acak)" },
  "gm.srv.gbFell": { en: "💥 The glass shattered! {name} fell at row {n} — drink 1 cup 🍺", zh: "💥 玻璃碎了！{name} 在第 {n} 排掉下去——喝1杯 🍺", id: "💥 Kacanya pecah! {name} jatuh di baris {n} — minum 1 gelas 🍺" },
  "gm.srv.gbFellAuto": { en: "💥 The glass shattered! {name} fell at row {n} — drink 1 cup 🍺 (time ran out)", zh: "💥 玻璃碎了！{name} 在第 {n} 排掉下去——喝1杯 🍺（超时）", id: "💥 Kacanya pecah! {name} jatuh di baris {n} — minum 1 gelas 🍺 (waktu habis)" },
  "gm.srv.gbDoneFell": { en: "🌉 {names} crossed! {fell} fell — drink 1 cup each 🍺", zh: "🌉 {names} 过桥了！{fell} 掉下去了——每人喝1杯 🍺", id: "🌉 {names} berhasil menyeberang! {fell} jatuh — masing-masing minum 1 gelas 🍺" },
  "gm.srv.gbDoneAll": { en: "🌉 {names} crossed! Nobody fell!", zh: "🌉 {names} 过桥了！没人掉下去！", id: "🌉 {names} berhasil menyeberang! Tidak ada yang jatuh!" },
  "gm.srv.gbNone": { en: "Nobody made it across — no winners! Everyone drinks 🍺", zh: "没人过桥——没有赢家！所有人喝 🍺", id: "Tidak ada yang berhasil menyeberang — tidak ada pemenang! Semua minum 🍺" },
  "gm.srv.dgStartFood": { en: "✏️ {name} is drawing — guess the food!", zh: "✏️ {name} 正在画——猜猜是什么食物！", id: "✏️ {name} sedang menggambar — tebak makanannya!" },
