  "gm.srv.dgHint": { en: "💡 Hint: a letter was revealed!", zh: "💡 提示：揭示了一个字母！", id: "💡 Petunjuk: satu huruf dibuka!" },
  "gm.srv.dgWin0": { en: "🎉 {name} guessed \"{word}\"! {name} & {drawer} win — nobody drinks 🍺", zh: "🎉 {name} 猜中了“{word}”！{name} 和 {drawer} 获胜——没人要喝 🍺", id: "🎉 {name} menebak \"{word}\"! {name} & {drawer} menang — tidak ada yang minum 🍺" },
