  "gm.srv.dgLose": { en: "{reason} The word was \"{word}\" — nobody got it, everyone drinks (drawer too) 🍺", zh: "{reason} 答案是“{word}”——没人猜中，所有人都喝（画手也喝）🍺", id: "{reason} Katanya \"{word}\" — tidak ada yang benar, semua minum (penggambar juga) 🍺" },
  "gm.srv.memFirst": { en: "{name} goes first — flip 2 cards 🃏", zh: "{name} 先开始——翻2张牌 🃏", id: "{name} mulai duluan — buka 2 kartu 🃏" },
